use crate::{bq088 as b,model::*,unit_support::*};
fn setup()->(Game,String){let mut g=game();fund(&mut g,0,"BQ092",1);let id=held(&mut g,b::ID,0);(g,id)}
fn play(id:&str)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),region:Some(0),option:Some("generate".into()),..Action::new("play")}}
fn top(g:&mut Game){for _ in 0..40{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
#[test]fn bq088_once_generates_real_slow_walker(){assert_current_serial_catalog();let(mut g,id)=setup();let before=g.players[0].deck.len();act(&mut g,0,play(&id));top(&mut g);assert_eq!(g.players[0].deck.len(),before-1);let c=g.regions[0].cards.iter().find(|c|c.definition==b::TOKEN).unwrap();assert!(c.generated.is_some()&&c.exhausted);assert!(g.bq088_continuations.is_empty());restore(&mut g);}
#[test]fn bq088_optional_repeat_is_bounded_and_restorable(){let(mut g,id)=setup();g.players[0].society_zone.secrecy=2;act(&mut g,0,play(&id));top(&mut g);for _ in 0..2{restore(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq088-repeat");choose(&mut g,vec!["repeat".into()]);}assert!(g.pending.is_none());assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition==b::TOKEN).count(),3);assert!(g.bq088_continuations.is_empty());restore(&mut g);}
fn host(g:&mut Game,seat:usize)->String{let c=g.make_card("BQ092",seat);let id=c.id.clone();g.attachments.push(Attachment{card:c,host_id:g.regions[0].card.id.clone()});id}
fn sealing(id:&str,host:&str)->Action{Action{option:Some("seal".into()),target_id:Some(host.into()),..play(id)}}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn bq088_seals_newly_milled_corpse_and_teammate_grave_but_not_enemy(){let(mut g,id)=setup();let h=host(&mut g,1);g.players[0].deck.clear();let corpse=g.make_card("XQ46",0);g.players[0].deck.push(corpse);for seat in [1,2]{let c=g.make_card("XQ46",seat);g.players[seat].graveyard.push(c);}act(&mut g,0,sealing(&id,&h));top(&mut g);restore(&mut g);let p=g.pending.as_ref().unwrap();assert_eq!(p.choice.kind,"bq088-seal");assert_eq!(p.choice.options.len(),2);let teammate=g.players[1].graveyard[0].id.clone();choose(&mut g,vec![teammate]);assert_eq!(g.sealed_cards.iter().filter(|s|s.host_id==h&&s.card.definition=="XQ46").count(),1);assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="XQ46").count(),1);assert_eq!(g.players[2].graveyard.len(),1);restore(&mut g);}
#[test]fn bq088_can_decline_seal_and_repetition_and_empty_deck_does_not_invent_a_card(){let(mut g,id)=setup();g.players[0].deck.clear();g.players[0].society_zone.secrecy=2;let h=host(&mut g,0);let c=g.make_card("XQ46",0);g.players[0].graveyard.push(c);act(&mut g,0,sealing(&id,&h));top(&mut g);choose(&mut g,vec![]);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"bq088-repeat");choose(&mut g,vec![]);assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition==b::TOKEN).count(),1);assert!(g.players[0].deck.is_empty()&&g.sealed_cards.is_empty());assert!(!g.players[0].eliminated);restore(&mut g);}
#[test]fn bq088_real_rumor_checkpoint_resumes_once_and_rejects_duplicate_carrier(){for accept in [false,true]{let(mut g,id)=setup();let h=field(&mut g,"JC125",0);g.players[0].deck.clear();let c=g.make_card("WM042",0);g.players[0].deck.push(c);act(&mut g,0,play(&id));top(&mut g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"rumor");assert!(!g.regions[0].cards.iter().any(|c|c.definition==b::TOKEN));restore(&mut g);let mut x=g.clone();let e=x.effects.iter().find(|e|matches!(e,Effect::Frame{frame}if frame.source.card.definition==b::ID)).unwrap().clone();x.effects.push_back(e);bad(&g,&x);choose(&mut g,if accept{vec![h]}else{vec![]});assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition==b::TOKEN).count(),1);assert!(g.bq088_continuations.is_empty());restore(&mut g);}}
#[test]fn bq088_corrupt_pending_and_actual_transaction_rejected(){let(mut g,id)=setup();act(&mut g,0,play(&id));for n in 0..3{let mut x=g.clone();let item=x.stack.last_mut().unwrap();match n{0=>item.frame=None,1=>item.frame.as_mut().unwrap().source.card.definition="JC001".into(),_=>item.frame.as_mut().unwrap().steps.clear()};bad(&g,&x);}g.players[0].society_zone.secrecy=1;top(&mut g);for n in 0..7{let mut x=g.clone();match n{0=>x.bq088_continuations.clear(),1=>x.bq088_continuations.push(x.bq088_continuations[0].clone()),2=>x.pending.as_mut().unwrap().choice.min=Some(1),3=>x.pending.as_mut().unwrap().choice.options.clear(),4=>x.pending.as_mut().unwrap().seat=1,_=>{let ChoiceResolution::Frame{frame,..}=&mut x.pending.as_mut().unwrap().resolution else{panic!()};if n==5{frame.cursor=1;}else{frame.steps.clear();}}}bad(&g,&x);}let p=g.pending.as_ref().unwrap();let a=Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![]),..Action::new("choose")};reject(&mut g,1,a.clone());reject(&mut g,0,Action{amount:Some(9),..a.clone()});act(&mut g,0,a.clone());reject(&mut g,0,a);restore(&mut g);}
#[test]fn bq088_response_host_control_and_region_instance_cancel_without_refund(){for n in 0..3{let(mut g,id)=setup();let h=host(&mut g,0);act(&mut g,0,sealing(&id,&h));match n{0=>g.attachments.iter_mut().find(|a|a.card.id==h).unwrap().card.controller=2,1=>g.regions[0].card=g.make_card("DQJC115",0),_=>{g.return_hand(&h);}}top(&mut g);assert_eq!(g.resources(0),0);assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition==b::TOKEN));restore(&mut g);}}
#[test]fn bq088_walker_lifecycle_and_zero_reveal_preserve_birth_and_slow(){let(mut g,id)=setup();act(&mut g,0,play(&id));top(&mut g);let id=g.regions[0].cards.iter().find(|c|c.definition==b::TOKEN).unwrap().id.clone();let birth=g.board(&id).unwrap().1.generated.clone();g.hide_in_place(&id);let id=g.regions[0].cards.iter().find(|c|c.generated==birth).unwrap().id.clone();g.begin_window(Window::Action(0));act(&mut g,0,Action{card_id:Some(id),..Action::new("reveal")});restore(&mut g);top(&mut g);let c=g.regions[0].cards.iter().find(|c|c.generated==birth).unwrap();assert!(c.exhausted&&!c.face_down);let id=c.id.clone();let h=field(&mut g,"JC125",0);let(_,c)=g.leave_board(&id).unwrap();g.seal_card_on_valid_host(c,0,&h);restore(&mut g);assert_eq!(g.sealed_cards.len(),1);g.return_hand(&h);assert!(g.sealed_cards.is_empty());assert!(!g.batch3_physical_cards().any(|c|c.generated==birth));restore(&mut g);}

use crate::{catalog,abi112_review_play_tests::Trace};
fn count(g:&Game)->usize{g.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition==b::TOKEN).count()}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn natural()->serde_json::Value{use crate::deck;fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="bq088-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("BQ092",3),("JC125",44)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("bq088".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}let(seed,g)=(1..4097).find_map(|seed|{let g=construct(seed);(g.players[0].hand.iter().any(|c|c.definition==b::ID)&&g.players[0].hand.iter().filter(|c|c.definition=="BQ092").count()>=1).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"bq088-natural-fifty-generate".into(),821);let mut done=false;for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&[b::ID,"BQ092"].contains(&c.definition.as_str())));t.choose(opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let gray=g.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="黑").count();let a=if gray<1{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ092")))}else if g.players[0].assets.len()<1{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC125")))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY)&&a.action.option.as_deref()==Some("generate"))};if let Some(a)=a{if a.action.kind=="play"{done=true;}t.action(0,a.action.clone());}else{t.pass();}}assert!(done);assert_eq!(count(&t.room.game),1);let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
fn prepared(seal:bool,rumor:bool)->serde_json::Value{let(mut g,id)=setup();g.players[0].society_zone.secrecy=1;let h=host(&mut g,1);g.players[0].deck.clear();for _ in 0..3{let c=g.make_card(if rumor{"WM042"}else{"XQ46"},0);g.players[0].deck.push(c);}if rumor{field(&mut g,"JC125",0);}let mut t=Trace::new_preserving_rng(g,format!("bq088-prepared-{}",if rumor{"rumor"}else if seal{"seal"}else{"repeat"}),831+usize::from(seal)+2*usize::from(rumor));t.action(0,if seal{sealing(&id,&h)}else{play(&id)});for _ in 0..80{if let Some(p)=t.room.game.pending.clone(){let ids=if p.choice.kind=="bq088-repeat"{vec!["repeat".into()]}else if p.choice.kind=="bq088-seal"||p.choice.kind=="rumor"{vec![p.choice.options[0].id.clone()]}else{vec![]};t.choose(ids);}else if !t.room.game.stack.is_empty(){t.pass();}else{break;}}assert_eq!(count(&t.room.game),2);assert!(t.room.game.bq088_continuations.is_empty());duplicate(t.value())}
#[test]fn bq088_native_natural_repeat_seal_rumor_export(){let cases=vec![natural(),prepared(false,false),prepared(true,false),prepared(false,true)];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/bq088.rs",include_bytes!("bq088.rs").as_slice()),("rust-game/src/bq088_tests.rs",include_bytes!("bq088_tests.rs").as_slice()),("rust-game/src/generated.rs",include_bytes!("generated.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("BQ088_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}
#[test]fn bq088_illegal_host_payload_and_missing_loyalty_do_not_pay(){let(mut g,id)=setup();let enemy=host(&mut g,2);let ordinary=field(&mut g,"JC125",0);for a in [sealing(&id,&enemy),sealing(&id,&ordinary),Action{amount:Some(9),..play(&id)},Action{target_id:Some(enemy),..play(&id)}]{reject(&mut g,0,a);}assert_eq!(g.resources(0),1);g.players[0].assets.clear();fund(&mut g,0,"JC069",1);reject(&mut g,0,play(&id));assert_eq!(g.resources(0),1);}
#[test]fn bq088_repeat_uses_original_resolution_limit_and_rejects_wait_beyond_limit(){let(mut g,id)=setup();act(&mut g,0,play(&id));g.players[0].society_zone.secrecy=1;top(&mut g);g.players[0].society_zone.secrecy=4;restore(&mut g);let mut x=g.clone();let ChoiceResolution::Frame{frame,..}=&mut x.pending.as_mut().unwrap().resolution else{panic!()};frame.steps[0].op=crate::rules::Op::BQ088(b::Program::Start{limit:Some(1),round:1});x.bq088_continuations[0].frame=(**frame).clone();bad(&g,&x);choose(&mut g,vec!["repeat".into()]);assert!(g.pending.is_none());assert_eq!(count(&g),2);restore(&mut g);}
